Object.assign(labels,{rush_debt:'Rushing debt · NFL NGS',rush_baseline_gap:'Rushing gap · local baseline',opp_light_box_rate:'Opponent light boxes · charted only',opp_charted_carries:'Opponent charted carries',ngs_rush_over_expected:'Yards over expected · NFL NGS',ngs_rush_games:'NGS sample games',ngs_time_to_throw:'Time to throw · NFL NGS',ngs_separation:'Separation · NFL NGS'});
labels.rz_attempts_pg='Red-zone attempts / game';
